BEGIN;
UPDATE public.config SET value='true' WHERE key='multi_tenant_enabled';
INSERT INTO auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) VALUES('ce8f8da2-0e18-4200-bb52-977aac215332','instagram-rollback@example.invalid',now(),'{}','{}');
SELECT set_config('request.jwt.claims','{"sub":"ce8f8da2-0e18-4200-bb52-977aac215332","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT public.tenant_onboard('Instagram rollback');
RESET ROLE;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','ce8f8da2-0e18-4200-bb52-977aac215332','role','authenticated','app_metadata',(SELECT raw_app_meta_data FROM auth.users WHERE id='ce8f8da2-0e18-4200-bb52-977aac215332'))::text,true);
DO $$ DECLARE tid uuid:=public.get_tenant_id();pid uuid;sid uuid;mid uuid;cid uuid:=gen_random_uuid();tok uuid;f jsonb;c jsonb;r jsonb;lid uuid; igid uuid; fields jsonb;req uuid:=gen_random_uuid();BEGIN
 SELECT id INTO pid FROM public.sales_pipelines WHERE tenant_id=tid LIMIT 1;
 SELECT id INTO sid FROM public.sales_pipeline_stages WHERE pipeline_id=pid AND NOT is_won AND NOT is_lost ORDER BY position LIMIT 1;
 SELECT id INTO mid FROM public.team_members WHERE tenant_id=tid LIMIT 1;
 IF public.normalize_instagram('https://www.instagram.com/QA.Test/?igsh=1')<>'qa.test' THEN RAISE EXCEPTION 'normalization';END IF;
 fields:='[{"id":"nome","type":"text","label":"Nome","required":true,"map_to":"nome"},{"id":"email","type":"email","label":"Email","required":true,"map_to":"email"},{"id":"ig","type":"instagram","label":"Instagram","required":false,"map_to":"instagram"}]';
 f:=public.forms_admin('save_publish',NULL,jsonb_build_object('name','Form IG QA','fields',fields,'settings',jsonb_build_object('pipeline_id',pid,'stage_id',sid,'responsible_id',mid),'style','{}'::jsonb));
 r:=public.forms_public_submit((f->>'id')::uuid,req,'{"nome":"QA Instagram","email":"ig-form@example.invalid","ig":"@QA.Test"}','{}',repeat('a',64));
 SELECT id INTO lid FROM public.leads WHERE tenant_id=tid AND email='ig-form@example.invalid';
 IF lid IS NULL OR NOT EXISTS(SELECT 1 FROM public.instagram_enrichment_jobs WHERE lead_id=lid AND username='qa.test' AND status='pending') THEN RAISE EXCEPTION 'form queue';END IF;
 PERFORM public.forms_public_submit((f->>'id')::uuid,req,'{"nome":"QA Instagram","email":"ig-form@example.invalid","ig":"@QA.Test"}','{}',repeat('a',64));
 IF (SELECT submissions_count FROM public.marketing_forms WHERE id=(f->>'id')::uuid)<>1 THEN RAISE EXCEPTION 'idempotency';END IF;
 PERFORM public.complete_instagram_enrichment(lid,'qa.test','{"full_name":"QA Instagram","biography":"Bio de teste","instagram_user_id":"123","is_private":false,"is_verified":false,"follower_count":100,"following_count":10,"media_count":2}');
 IF NOT EXISTS(SELECT 1 FROM public.leads l JOIN public.instagram_profiles p ON p.id::text=l.instagram_profile_id AND p.tenant_id=l.tenant_id WHERE l.id=lid AND p.biography='Bio de teste') THEN RAISE EXCEPTION 'enrichment';END IF;
 c:=public.inbound_admin('create',cid,'{"name":"Página IG"}');tok:=(c->>'token')::uuid;
 c:=public.inbound_admin('save',cid,jsonb_build_object('name','Página IG','pipeline_id',pid,'stage_id',sid,'method','fixed','members',jsonb_build_array(mid),'mappings','[{"source":"nome","target":"name","required":true},{"source":"email","target":"email","required":true},{"source":"ig","target":"instagram","required":false}]'::jsonb),1);
 c:=public.inbound_admin('status',cid,'{"status":"active"}',(c->>'revision')::int);
 r:=public.inbound_receive(tok,gen_random_uuid(),'{"nome":"QA Instagram","email":"ig-form@example.invalid","ig":"https://instagram.com/novo.qa/"}');
 IF r->>'status'<>'processed' THEN RAISE EXCEPTION 'inbound %',r;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leads WHERE id=lid AND instagram='novo.qa' AND instagram_profile_id IS NULL) THEN RAISE EXCEPTION 'changed handle must clear old profile';END IF;
 IF (SELECT count(*) FROM public.leads WHERE tenant_id=tid)<>1 THEN RAISE EXCEPTION 'duplicate lead';END IF;
 IF (SELECT source FROM public.leads WHERE id=lid)<>'Formulário | Form IG QA' THEN RAISE EXCEPTION 'source overwritten';END IF;
 PERFORM public.complete_instagram_enrichment(lid,'qa.test','{}');
 IF EXISTS(SELECT 1 FROM public.leads WHERE id=lid AND instagram_profile_id IS NOT NULL) THEN RAISE EXCEPTION 'stale worker';END IF;
 IF has_function_privilege('authenticated','public.complete_instagram_enrichment(uuid,text,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'privilege leak';END IF;
 INSERT INTO public.instagram_business_accounts(tenant_id,instagram_business_id,instagram_username,name,access_token,status) VALUES(tid,'qa-ig-form-test','qa_account','QA','not-a-real-token','connected') RETURNING id INTO igid;
 INSERT INTO public.zernio_accounts(id,tenant_id,provider,platform,profile_id,name,username,instagram_account_id,is_active,pipeline_id,stage_id,member_id) VALUES('qa-ig-account',tid,'meta','instagram','','QA','qa_account',igid,true,pid,sid,mid);
 r:=public.social_record_interaction('qa-ig-account','comment:123','{"id":"qa-comment-1","text":"Quero participar","sender":{"id":"123","username":"novo.qa"},"kind":"post_comment","comment_id":"qa-comment-1","reference_id":"qa-post-1","reference_type":"post"}');
 IF r#>>'{conversation,lead_id}' IS DISTINCT FROM lid::text THEN RAISE EXCEPTION 'comment was not linked to form lead: %',r;END IF;
 IF (SELECT count(*) FROM public.leads WHERE tenant_id=tid)<>1 THEN RAISE EXCEPTION 'comment duplicated lead';END IF;
 INSERT INTO public.social_accounts(tenant_id,zernio_account_id,platform) VALUES(tid,'qa-social','instagram');
END $$;
SET LOCAL ROLE authenticated;
DO $$ BEGIN IF (SELECT count(*) FROM public.social_accounts)<>1 THEN RAISE EXCEPTION 'RLS leaked accounts';END IF;END $$;
RESET ROLE;
ROLLBACK;
